var moves = $('Buscar Ajustes de Inventario').first().json.result || [];
var params = $('Calcular Ventana de Tiempo').first().json;

if (moves.length === 0) {
  return [{ json: { output: 'sin_ajustes' } }];
}

// Agrupar por referencia/ajuste
var grupos = {};
for (var i = 0; i < moves.length; i++) {
  var m = moves[i];
  var ref = m.reference || m.origin || m.name || 'Sin referencia';
  if (!grupos[ref]) grupos[ref] = [];
  grupos[ref].push(m);
}

var totalMovs = moves.length;
var totalGrupos = Object.keys(grupos).length;

var filas = '';
var bgToggle = false;
Object.keys(grupos).forEach(function(ref) {
  var movs = grupos[ref];
  movs.forEach(function(m, idx) {
    var esperado = parseFloat(m.product_uom_qty) || 0;
    var real = parseFloat(m.quantity) || 0;
    var diff = real - esperado;
    var diffColor = diff < 0 ? '#dc3545' : diff > 0 ? '#28a745' : '#6c757d';
    var diffStr = (diff > 0 ? '+' : '') + diff.toFixed(2);
    var bg = bgToggle ? '#f8f9fa' : '#ffffff';
    var producto = m.product_id ? m.product_id[1] : 'N/A';
    var locOrigen = m.location_id ? m.location_id[1] : '';
    var locDest = m.location_dest_id ? m.location_dest_id[1] : '';
    var fecha = m.date ? m.date.replace('T', ' ').substring(0, 16) : '';
    var empresa = m.company_id ? m.company_id[1] : '';

    if (idx === 0) {
      filas += '<tr style="background:' + bg + '">';
      filas += '<td rowspan="' + movs.length + '" style="padding:8px 10px;border:1px solid #dee2e6;vertical-align:top;font-weight:600;">' + ref + '</td>';
      filas += '<td rowspan="' + movs.length + '" style="padding:8px 10px;border:1px solid #dee2e6;vertical-align:top;font-size:12px;color:#555;">' + fecha + '</td>';
      filas += '<td rowspan="' + movs.length + '" style="padding:8px 10px;border:1px solid #dee2e6;vertical-align:top;font-size:12px;color:#555;">' + empresa + '</td>';
    } else {
      filas += '<tr style="background:' + bg + '">';
    }

    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;">' + producto + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;">' + esperado.toFixed(2) + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;">' + real.toFixed(2) + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;text-align:center;font-weight:700;color:' + diffColor + ';">' + diffStr + '</td>';
    filas += '<td style="padding:8px 10px;border:1px solid #dee2e6;font-size:12px;color:#555;">' + locOrigen + ' → ' + locDest + '</td>';
    filas += '</tr>';

    bgToggle = !bgToggle;
  });
});

var tabla = '<table style="width:100%;border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;">' +
  '<thead>' +
  '<tr style="background:#0066CC;color:#fff;">' +
  '<th style="padding:10px;text-align:left;">Referencia</th>' +
  '<th style="padding:10px;text-align:left;">Fecha</th>' +
  '<th style="padding:10px;text-align:left;">Empresa</th>' +
  '<th style="padding:10px;text-align:left;">Producto</th>' +
  '<th style="padding:10px;text-align:center;">Cant. Esperada</th>' +
  '<th style="padding:10px;text-align:center;">Cant. Real</th>' +
  '<th style="padding:10px;text-align:center;">Diferencia</th>' +
  '<th style="padding:10px;text-align:left;">Ubicación</th>' +
  '</tr>' +
  '</thead>' +
  '<tbody>' + filas + '</tbody>' +
  '</table>';

return [{ json: {
  tabla: tabla,
  totalMovs: totalMovs,
  totalGrupos: totalGrupos,
  now_label: params.now_label
} }];
